    let ans = 0;
    const stack = [0];
    for (const num of nums) {
        while (stack.length > 0 && stack[stack.length - 1] > num) {
            stack.pop();
        }
        if (stack.length === 0 || stack[stack.length - 1] < num) {
            ans++;
            stack.push(num);
